import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import "../styles/admin.css";
import "../styles/components.css";

function ManageChannelsPage() {
  const navigate = useNavigate();
  const [channels, setChannels] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [message, setMessage] = useState("");
  const [editingId, setEditingId] = useState(null);
  const [formData, setFormData] = useState({ name: "", description: "" });
  const [showForm, setShowForm] = useState(false);
  
  const token = localStorage.getItem("token");
  const isAdmin = localStorage.getItem("is_staff") === "true";

  useEffect(() => {
    if (!token || !isAdmin) {
      navigate("/login");
      return;
    }
    fetchChannels();
  }, [token, isAdmin, navigate]);

  const fetchChannels = async () => {
    try {
      const res = await fetch("http://127.0.0.1:8000/api/channels/", {
        headers: {
          "Content-Type": "application/json",
          ...(token && { Authorization: `Bearer ${token}` }),
        },
      });

      if (!res.ok) {
        throw new Error("Не вдалося завантажити канали");
      }

      const data = await res.json();
      setChannels(Array.isArray(data) ? data : data.results || []);
      setLoading(false);
    } catch (err) {
      console.error("Помилка завантаження каналів:", err);
      setError("Помилка завантаження каналів");
      setLoading(false);
    }
  };

  const handleCreate = async (e) => {
    e.preventDefault();
    setError("");
    setMessage("");

    if (!formData.name.trim()) {
      setError("Назва каналу обов'язкова");
      return;
    }

    try {
      const res = await fetch("http://127.0.0.1:8000/api/channels/", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          name: formData.name.trim(),
          description: formData.description.trim() || "",
        }),
      });

      const data = await res.json();

      if (!res.ok) {
        setError(data.detail || data.name?.[0] || "Помилка створення каналу");
        return;
      }

      setMessage("Канал успішно створено!");
      setFormData({ name: "", description: "" });
      setShowForm(false);
      fetchChannels();
    } catch (err) {
      console.error("Помилка створення каналу:", err);
      setError("Помилка створення каналу, спробуйте ще раз");
    }
  };

  const handleEdit = (channel) => {
    setEditingId(channel.id);
    setFormData({ name: channel.name, description: channel.description || "" });
    setShowForm(true);
    setError("");
    setMessage("");
  };

  const handleUpdate = async (e) => {
    e.preventDefault();
    setError("");
    setMessage("");

    if (!formData.name.trim()) {
      setError("Назва каналу обов'язкова");
      return;
    }

    try {
      const res = await fetch(`http://127.0.0.1:8000/api/channels/${editingId}/`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          name: formData.name.trim(),
          description: formData.description.trim() || "",
        }),
      });

      const data = await res.json();

      if (!res.ok) {
        setError(data.detail || data.name?.[0] || "Помилка оновлення каналу");
        return;
      }

      setMessage("Канал успішно оновлено!");
      setFormData({ name: "", description: "" });
      setEditingId(null);
      setShowForm(false);
      fetchChannels();
    } catch (err) {
      console.error("Помилка оновлення каналу:", err);
      setError("Помилка оновлення каналу, спробуйте ще раз");
    }
  };

  const handleDelete = async (channelId) => {
    if (!window.confirm("Ви впевнені, що хочете видалити цей канал?")) {
      return;
    }

    try {
      const res = await fetch(`http://127.0.0.1:8000/api/channels/${channelId}/`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (!res.ok) {
        throw new Error("Не вдалося видалити канал");
      }

      setMessage("Канал успішно видалено!");
      fetchChannels();
    } catch (err) {
      console.error("Помилка видалення каналу:", err);
      setError("Помилка видалення каналу");
    }
  };

  const handleCancel = () => {
    setFormData({ name: "", description: "" });
    setEditingId(null);
    setShowForm(false);
    setError("");
    setMessage("");
  };

  if (loading) {
    return (
      <div className="admin-page">
        <div className="loading-state">Завантаження...</div>
      </div>
    );
  }

  return (
    <div className="admin-page">
      <h1>Управління каналами</h1>

      {error && <div className="alert alert-error">{error}</div>}
      {message && <div className="alert alert-success">{message}</div>}

      {!showForm ? (
        <button
          className="btn btn-primary"
          onClick={() => {
            setShowForm(true);
            setEditingId(null);
            setFormData({ name: "", description: "" });
            setError("");
            setMessage("");
          }}
          style={{ marginBottom: "var(--spacing-lg)" }}
        >
          + Створити новий канал
        </button>
      ) : (
        <div className="card" style={{ marginBottom: "var(--spacing-lg)" }}>
          <h3>{editingId ? "Редагувати канал" : "Створити новий канал"}</h3>
          <form onSubmit={editingId ? handleUpdate : handleCreate}>
            <label>
              Назва каналу:
              <input
                className="input"
                type="text"
                placeholder="Введіть назву каналу"
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                required
              />
            </label>

            <label>
              Опис каналу (опціонально):
              <textarea
                className="input create-article-textarea"
                placeholder="Введіть опис каналу"
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
              />
            </label>

            <div style={{ display: "flex", gap: "var(--spacing-sm)", marginTop: "var(--spacing-md)" }}>
              <button className="btn btn-primary" type="submit">
                {editingId ? "Зберегти зміни" : "Створити канал"}
              </button>
              <button className="btn btn-secondary" type="button" onClick={handleCancel}>
                Скасувати
              </button>
            </div>
          </form>
        </div>
      )}

      <div className="admin-table-wrapper">
        <table className="admin-table">
          <thead>
            <tr>
              <th>ID</th>
              <th>Назва</th>
              <th>Опис</th>
              <th>Дата створення</th>
              <th>Дії</th>
            </tr>
          </thead>
          <tbody>
            {channels.length === 0 ? (
              <tr>
                <td colSpan="5" style={{ textAlign: "center", padding: "var(--spacing-xl)" }}>
                  <div className="empty-state">
                    <p>Каналів не знайдено</p>
                  </div>
                </td>
              </tr>
            ) : (
              channels.map((channel) => (
                <tr key={channel.id}>
                  <td>{channel.id}</td>
                  <td>{channel.name}</td>
                  <td>{channel.description || <em style={{ color: "var(--text-secondary)" }}>Немає опису</em>}</td>
                  <td>
                    {channel.created_at
                      ? new Date(channel.created_at).toLocaleDateString("uk-UA", {
                          year: "numeric",
                          month: "2-digit",
                          day: "2-digit",
                        })
                      : "Н/Д"}
                  </td>
                  <td>
                    <div style={{ display: "flex", gap: "var(--spacing-xs)" }}>
                      <button
                        className="table-action-btn"
                        style={{ backgroundColor: "var(--bg-secondary)", color: "var(--text-primary)", border: "1px solid var(--border-color)" }}
                        onClick={() => handleEdit(channel)}
                      >
                        Редагувати
                      </button>
                      <button
                        className="table-action-btn table-action-btn-danger"
                        onClick={() => handleDelete(channel.id)}
                      >
                        Видалити
                      </button>
                    </div>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

export default ManageChannelsPage;
